// Convierte un mensaje de Gmail (Gmail Trigger / nodo Gmail con "Simplify" desactivado) al JSON de mailcat.
const clean = (s) => (s === undefined || s === null ? '' : String(s));
return $input.all().map(({ json: m }) => {
  const from = m.from && m.from.value && m.from.value[0];
  const sender = from
    ? (from.name ? `${from.name} <${from.address}>` : from.address)
    : clean(m.from && m.from.text ? m.from.text : m.from);
  // Las etiquetas propias de Gmail (CATEGORY_PROMOTIONS...) son una señal útil para mailcat.
  const labels = (m.labelIds || []).map(l => String(l).toLowerCase().replace(/_/g, ' ')).join(',');
  const h = m.headers || {};
  const headers = {};
  for (const k of ['list-unsubscribe', 'list-id', 'precedence', 'auto-submitted']) {
    if (h[k]) headers[k] = clean(h[k]);
  }
  if (labels) headers['x-gmail-labels'] = labels;
  return { json: {
    id: `gmail-${m.id}`,
    sender,
    subject: clean(m.subject),
    body: clean(m.text || m.snippet).slice(0, 20000),
    message_id: clean(h['message-id']).replace(/[<>]/g, ''),
    in_reply_to: clean(h['in-reply-to']).replace(/[<>]/g, ''),
    received_at: m.date ? new Date(m.date).toISOString() : undefined,
    headers,
  } };
});
